<style>
:root{--ser103-accent:#ad8d89;--ser103-accent-dark:#8d706d;--ser103-ink:#202020;--ser103-muted:#666;--ser103-soft:#f4f4f4;--ser103-line:#e4e0df;--ser103-script:"Allura",cursive;--ser103-sans:"Be Vietnam Pro",sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ser103-ink);background:#fff;font-family:var(--ser103-sans)}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.ser103-page img{display:block;max-width:100%}.ser103-main{overflow:hidden}.ser103-container{width:min(1540px,calc(100% - 64px));margin:auto}.ser103-section{position:relative;padding:110px 0}.ser103-heading{max-width:780px;margin:0 auto 58px;text-align:center}.ser103-heading>span,.ser103-contact__form>span{display:inline-block;color:var(--ser103-accent);font-family:var(--ser103-script);font-size:29px;border-bottom:1px solid currentColor}.ser103-heading h2,.ser103-contact h2{margin:12px 0 14px;font-size:clamp(36px,4vw,58px);font-weight:500;line-height:1.15}.ser103-heading p{margin:0;color:var(--ser103-muted);line-height:1.7}
.ser103-header{position:sticky;top:0;z-index:80;background:#fff;border-top:1px solid #222;transition:.25s}.ser103-header.is-scrolled{box-shadow:0 10px 32px #00000012}.ser103-header__inner{display:flex;align-items:center;min-height:112px;gap:34px}.ser103-brand{font-size:58px;font-weight:800;letter-spacing:-.06em}.ser103-brand img{max-width:230px;max-height:68px;object-fit:contain}.ser103-nav{display:flex;align-items:center;gap:48px;margin-left:auto}.ser103-nav a{font-size:16px;font-weight:600;text-transform:uppercase}.ser103-nav a:hover{color:var(--ser103-accent)}.ser103-header__actions{display:flex;align-items:center;gap:14px}.ser103-header__actions>a,.ser103-header__actions>button:not(.ser103-booking-button){display:grid;width:42px;height:42px;place-items:center;border:0;background:transparent;cursor:pointer;font-size:20px}.ser103-languages{display:flex;gap:6px}.ser103-languages a{font-size:24px}.ser103-booking-button,.ser103-button{display:inline-flex;align-items:center;justify-content:center;gap:14px;min-height:58px;padding:0 28px;border:1px solid var(--ser103-accent);border-radius:8px;background:var(--ser103-accent);color:#fff;cursor:pointer;font-weight:700}.ser103-button.is-light{background:#fff;color:#151515;border-color:#ddd}.ser103-menu-toggle{display:none;border:0;background:none;font-size:26px}
.ser103-hero{position:relative;display:grid;min-height:760px;grid-template-columns:1fr 1fr;margin:0 40px 70px;background:var(--ser103-soft)}.ser103-hero__copy{display:flex;align-items:center;justify-content:center;flex-direction:column;padding:70px 9%;text-align:center}.ser103-hero__copy>p{margin:0 0 24px;color:var(--ser103-accent);font-family:var(--ser103-script);font-size:32px}.ser103-hero h1{max-width:760px;margin:0;color:var(--ser103-accent);font-size:clamp(46px,4vw,72px);font-weight:500;line-height:1.08;text-transform:uppercase}.ser103-hero__summary{max-width:700px;margin:30px auto;color:#383838;font-size:17px;line-height:1.75}.ser103-hero__actions{display:flex;gap:22px}.ser103-hero__visual{position:relative;min-height:760px;overflow:hidden}.ser103-hero__visual>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:.7s}.ser103-hero__visual>img.is-active{opacity:1}.ser103-hero__dots{position:absolute;bottom:14px;left:-15px;display:flex;gap:6px}.ser103-hero__dots button{width:13px;height:7px;padding:0;border:0;border-radius:8px;background:#ddd}.ser103-hero__dots button.is-active{width:29px;background:var(--ser103-accent)}
