.ser103-news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:38px}.ser103-news-grid article>a:first-child{display:block;overflow:hidden}.ser103-news-grid img{width:100%;height:470px;object-fit:cover}.ser103-news__meta{display:flex;gap:26px;margin:20px 0 14px;color:#777}.ser103-news__meta i{color:var(--ser103-accent)}.ser103-news-grid h3{margin:0;font-size:25px;line-height:1.35}.ser103-news-grid p{color:var(--ser103-muted);line-height:1.7}.ser103-more{display:inline-flex;gap:10px;color:var(--ser103-accent);font-weight:700}
