.ser103-gallery{position:relative;display:grid;grid-template-columns:repeat(5,1fr);gap:26px;padding:80px 10px}.ser103-gallery a{overflow:hidden}.ser103-gallery img{width:100%;height:390px;object-fit:cover;transition:.35s}.ser103-gallery a:hover img{transform:scale(1.04)}
