.xd-edit-block{position:absolute;top:18px;right:18px;z-index:20;padding:9px 14px;border:0;border-radius:999px;background:#222;color:#fff;cursor:pointer}.xd-editor[hidden],.xd-item-modal[hidden]{display:none!important}.xd-editor,.xd-item-modal{position:fixed;inset:0;z-index:150;display:grid;place-items:center;padding:20px;background:#0009}.xd-editor-card,.xd-item-card{width:min(900px,100%);max-height:92vh;overflow:auto;padding:24px;border-radius:16px;background:#fff}.xd-editor-head,.xd-item-card-head,.xd-editor-actions,.xd-item-actions,.xd-editor-items-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.xd-editor-grid,.xd-item-form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.xd-editor-field,.xd-item-form label,.xd-editor-source-grid label{display:grid;gap:6px}.xd-editor-field.is-wide,.xd-editor-items,.xd-editor-source{grid-column:1/-1}.xd-editor-field input,.xd-editor-field textarea,.xd-item-form input,.xd-item-form textarea,.xd-editor-source-grid input,.xd-editor-source-grid select{width:100%;padding:11px;border:1px solid #ddd;border-radius:8px}.xd-editor-hidden-json{display:none}.xd-editor-source-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.xd-editor-items{margin-top:12px;padding:14px;border:1px solid #ddd}.xd-editor-item{display:flex;justify-content:space-between;gap:12px;padding:12px;border-bottom:1px solid #eee}.xd-editor-actions,.xd-item-actions{justify-content:flex-end;margin-top:18px}.xd-editor-actions button,.xd-item-actions button,.xd-editor-add,.xd-editor-edit,.xd-editor-remove,.xd-editor-close,.xd-item-close{padding:9px 14px;border:0;border-radius:8px;cursor:pointer}.xd-editor-actions button[type=submit],.xd-item-actions button[type=submit],.xd-editor-add{background:var(--ser103-accent);color:#fff}.xd-editor-locale-tabs{display:flex;gap:8px;margin-bottom:15px}.xd-editor-locale-tab{padding:8px 14px;border:1px solid #ddd;border-radius:999px;background:#fff}.xd-editor-locale-tab.is-active{background:var(--ser103-accent);color:#fff}
