@media(max-width:900px){.ser103-container{width:min(100% - 36px,1540px)}.ser103-menu-toggle{display:block;margin-left:auto}.ser103-nav{position:absolute;top:88px;right:0;left:0;display:none;align-items:stretch;flex-direction:column;padding:18px 28px;background:#fff;box-shadow:0 16px 30px #0002}.ser103-nav.is-open{display:flex}.ser103-header__inner{min-height:88px}.ser103-header__actions>a,.ser103-header__actions>button:not(.ser103-booking-button),.ser103-languages{display:none}.ser103-booking-button span{display:none}.ser103-hero{grid-template-columns:1fr;margin:0}.ser103-hero__copy{min-height:500px}.ser103-hero__visual{min-height:600px}.ser103-about{display:block}.ser103-about__image.is-main{height:620px}.ser103-about__content{padding:80px 12%}.ser103-news-grid{grid-template-columns:1fr 1fr}.ser103-contact{grid-template-columns:1fr}.ser103-contact__image img{height:600px}.ser103-gallery{grid-template-columns:repeat(3,1fr)}.ser103-gallery a:nth-child(n+4){display:none}.ser103-detail{grid-template-columns:1fr}}
